<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch,shallowRef} from "vue";
import CrossCameraTrajectories from './CrossCameraTrajectories.vue';
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "leaflet.heat";
import type {Building} from "@/types";
type Metric="CARBON"|"ENERGY";type Ranked={building:Building;emission:number};type Feature={type:"Feature";properties:Record<string,unknown>;geometry:{type:"Polygon";coordinates:number[][][]}};type Collection={type:"FeatureCollection";features:Feature[]};
const props=defineProps<{buildings:Building[];buildingCarbon:Ranked[];metric:Metric}>(),emit=defineEmits<{building:[Building]}>();
const host=ref<HTMLDivElement>(),footprintCount=ref(0),namedCount=ref(0),linkedCount=ref(0),loadError=ref('');
const mapInstance=shallowRef<L.Map>();
const layers=ref({boundary:true,footprints:true,heat:true,energyHotspots:true,carbonHotspots:true,trajectory:false});
let map:L.Map|undefined,heat:L.HeatLayer|undefined,footprints=L.layerGroup(),boundary=L.layerGroup(),hotspots=L.layerGroup(),trajectory=L.layerGroup(),spatialFeatures:Feature[]=[];
const emissions=computed(()=>new Map(props.buildingCarbon.map(x=>[x.building.id,x.emission])));
function matched(buildingId:string){return props.buildings.find(item=>item.code===buildingId||item.metadata_json?.building_id===buildingId)}
function publicName(feature:Feature){return feature.properties.verified?String(feature.properties.name||'未核名建筑'):'未核名建筑'}
function featureCenter(feature:Feature):[number,number]{const ring=feature.geometry.coordinates[0],points=ring[0]?.[0]===ring.at(-1)?.[0]&&ring[0]?.[1]===ring.at(-1)?.[1]?ring.slice(0,-1):ring;return [points.reduce((s,p)=>s+p[1],0)/points.length,points.reduce((s,p)=>s+p[0],0)/points.length]}
const fmt=(value:number)=>value.toLocaleString('zh-CN',{maximumFractionDigits:1});
function businessValue(building:Building,metric:Metric){return metric==='CARBON'?Number(building.metadata_json?.annual_emission_tco2e??emissions.value.get(building.id)??0):Number(building.metadata_json?.annual_energy_kwh??0)}
function threshold(metric:Metric){const values=props.buildings.map(x=>businessValue(x,metric)).filter(x=>x>0).sort((a,b)=>a-b);return values.length?values[Math.max(0,Math.ceil(values.length*.75)-1)]:Number.POSITIVE_INFINITY}
function markerIcon(metric:Metric){const label=metric==='CARBON'?'高碳':'高耗',className=metric==='CARBON'?'carbon':'energy';return L.divIcon({className:'hotspot-host',html:`<span class="hotspot ${className}">${label}</span>`,iconSize:[42,22],iconAnchor:[21,11]})}
function syncLayer(group:L.LayerGroup,visible:boolean){if(!map)return;if(visible&&!map.hasLayer(group))group.addTo(map);if(!visible&&map.hasLayer(group))group.removeFrom(map)}
function renderLayers(){
  if(!map)return;footprints.clearLayers();hotspots.clearLayers();if(heat){heat.remove();heat=undefined}
  const rows:Array<{lat:number;lng:number;value:number}>=[];let linked=0;
  const energyThreshold=threshold('ENERGY'),carbonThreshold=threshold('CARBON');
  spatialFeatures.forEach(feature=>{
    const buildingId=String(feature.properties.building_id||''),name=publicName(feature),business=matched(buildingId);
    const value=business?businessValue(business,props.metric):0;
    if(business){linked++;const [lat,lng]=featureCenter(feature);rows.push({lat,lng,value});const energy=businessValue(business,'ENERGY'),carbon=businessValue(business,'CARBON'),tip=`${name}<br>年用电：${fmt(energy)} 千瓦时<br>年碳排：${fmt(carbon)} 吨二氧化碳当量`;if(layers.value.energyHotspots&&energy>=energyThreshold)L.marker([lat,lng-.000035],{icon:markerIcon('ENERGY'),keyboard:false}).bindTooltip(tip).on('click',()=>emit('building',business)).addTo(hotspots);if(layers.value.carbonHotspots&&carbon>=carbonThreshold)L.marker([lat,lng+.000035],{icon:markerIcon('CARBON'),keyboard:false}).bindTooltip(tip).on('click',()=>emit('building',business)).addTo(hotspots)}
    const layer=L.geoJSON(feature as never,{style:{color:business?'#00a99d':'#47747d',weight:business?2:1,fillColor:business?'#45d8bb':'#dce9e7',fillOpacity:business?.25:.12}});
    layer.bindTooltip(`<b>${name}</b><br>建筑编号：${buildingId}<br>${business?`年用电：${fmt(businessValue(business,'ENERGY'))} 千瓦时<br>年碳排：${fmt(businessValue(business,'CARBON'))} 吨二氧化碳当量<br>点击查看建筑详情`:'尚未绑定能碳业务对象'}`);
    if(business)layer.on('click',()=>emit('building',business));layer.addTo(footprints)
  });
  linkedCount.value=linked;syncLayer(footprints,layers.value.footprints);syncLayer(hotspots,layers.value.energyHotspots||layers.value.carbonHotspots);syncLayer(boundary,layers.value.boundary);syncLayer(trajectory,layers.value.trajectory);
  if(rows.length&&layers.value.heat){const max=Math.max(1,...rows.map(x=>x.value));heat=L.heatLayer(rows.map(x=>[x.lat,x.lng,Math.max(.18,x.value/max)] as L.HeatLatLngTuple),{radius:38,blur:30,maxZoom:20,minOpacity:.28,gradient:{.2:'#39c6ff',.45:'#38df9b',.7:'#ffd24d',1:'#ef3f35'}}).addTo(map)}
}
async function loadSpatial(){try{const [campus,buildings]=await Promise.all([fetch('/data/hbue/hbue_campus_boundary.geojson').then(r=>{if(!r.ok)throw new Error('校园边界加载失败');return r.json() as Promise<Collection>}),fetch('/data/hbue/hbue_buildings.geojson').then(r=>{if(!r.ok)throw new Error('建筑轮廓加载失败');return r.json() as Promise<Collection>})]);spatialFeatures=buildings.features;footprintCount.value=spatialFeatures.length;namedCount.value=spatialFeatures.filter(x=>Boolean(x.properties.verified)).length;const border=L.geoJSON(campus as never,{style:{color:'#008a91',weight:3,fillColor:'#9ce8da',fillOpacity:.04,dashArray:'8 5'}}).addTo(boundary);boundary.addTo(map!);const bounds=border.getBounds();map!.fitBounds(bounds,{padding:[8,8]});map!.setZoom(Math.min(19,map!.getZoom()+1));map!.setMaxBounds(bounds.pad(.35));renderLayers()}catch(error){loadError.value=(error as Error).message}}
onMounted(()=>{if(!host.value)return;map=L.map(host.value,{zoomControl:false,zoomAnimation:false,fadeAnimation:false,attributionControl:true,minZoom:14,maxZoom:20}).setView([30.42023,114.42966],16);mapInstance.value=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:20,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);void loadSpatial();setTimeout(()=>map?.invalidateSize(),0)});
watch(()=>[props.buildings,props.buildingCarbon,props.metric,layers.value],renderLayers,{deep:true});onBeforeUnmount(()=>{map?.stop();map?.remove();map=undefined});
</script>
<template><div class="campus-gis-shell" data-testid="campus-gis"><div ref="host" class="campus-gis-map"/><CrossCameraTrajectories :map="mapInstance" :enabled="layers.trajectory"/><div class="gis-title"><small>校园 GIS 能碳态势</small><b>湖北经济学院</b><span>WGS84 · EPSG:4326</span><em>建筑轮廓 {{footprintCount}} · 具名 {{namedCount}} · 业务绑定 {{linkedCount}}</em></div><div class="layer-control" data-testid="gis-layer-control"><b>图层控制</b><label><input v-model="layers.boundary" type="checkbox">校园边界</label><label><input v-model="layers.footprints" type="checkbox">建筑轮廓</label><label><input v-model="layers.heat" type="checkbox">{{metric==='CARBON'?'碳排热力':'能耗热力'}}</label><label><input v-model="layers.energyHotspots" type="checkbox">高能耗热点</label><label><input v-model="layers.carbonHotspots" type="checkbox">高碳排热点</label><label class="reserved"><input v-model="layers.trajectory" type="checkbox">跨镜轨迹</label><small>示范布点和示范活动路径；实时数据需后端鉴权</small></div><div class="gis-legend"><b>{{metric==='CARBON'?'碳排放热力':'综合能耗热力'}}</b><i></i><span>低</span><span>高</span></div><div class="gis-notice" :class="{error:loadError}">{{loadError||'校园边界与125栋建筑轮廓保持不变；能碳热力和热点仅对16栋已绑定建筑计算，未绑定建筑不分配业务指标。'}}</div></div></template>
<style scoped>
.campus-gis-shell,.campus-gis-map{position:absolute;inset:0}.campus-gis-shell{overflow:hidden;background:#c9e3e7}.campus-gis-map{z-index:1}.gis-title,.layer-control,.gis-legend,.gis-notice{position:absolute;z-index:500;background:#06384ee8;color:#effcff;border:1px solid #42c9d8;box-shadow:0 8px 24px #06253255}.gis-title{left:18px;top:18px;padding:11px 16px;border-left:4px solid #42e5d0;display:grid;gap:2px}.gis-title small,.gis-title span,.gis-title em{font-size:10px;color:#9bd1da;font-style:normal}.gis-title b{font-size:20px;letter-spacing:2px}.layer-control{right:18px;top:18px;padding:10px 12px;display:grid;grid-template-columns:1fr 1fr;gap:7px 12px;font-size:11px}.layer-control b,.layer-control small{grid-column:1/-1}.layer-control label{display:flex;align-items:center;gap:5px;cursor:pointer}.layer-control input{accent-color:#19cdb9}.layer-control small{color:#8fbfca;max-width:250px}.layer-control .reserved{color:#a7d5dd}.gis-legend{right:18px;bottom:70px;padding:9px 12px;display:grid;grid-template-columns:auto 18px 1fr auto;align-items:center;gap:7px;font-size:10px}.gis-legend b{grid-column:1/-1;font-size:11px}.gis-legend i{grid-column:1/-1;width:170px;height:8px;background:linear-gradient(90deg,#39c6ff,#38df9b,#ffd24d,#ef3f35);border-radius:8px}.gis-notice{left:18px;right:18px;bottom:16px;padding:8px 12px;font-size:10px;color:#bfe4e9}.gis-notice.error{border-color:#ff806b;color:#ffd1c8}.campus-gis-shell :deep(.leaflet-control-attribution){font-size:9px}.campus-gis-shell :deep(.leaflet-tooltip){background:#07384eee;border:1px solid #41c7d7;color:#fff;font:12px/1.6 "Microsoft YaHei",sans-serif}.campus-gis-shell :deep(.hotspot-host){background:transparent;border:0}.campus-gis-shell :deep(.hotspot){display:grid;place-items:center;width:42px;height:22px;border-radius:12px;color:#fff;font:bold 10px "Microsoft YaHei";box-shadow:0 0 0 2px #fff,0 2px 10px #06253299}.campus-gis-shell :deep(.hotspot.carbon){background:#e4483f}.campus-gis-shell :deep(.hotspot.energy){background:#ef9f22}
</style>
